class Solution {
    public int[] findErrorNums(int[] nums){
        int duplicate=0,missing=0;
        for(int item:nums){
            int value=Math.abs(item),index=value-1;
            if(nums[index]<0)duplicate=value;
            else nums[index]=-nums[index];
        }
        for(int i=0;i<nums.length;i++)if(nums[i]>0)missing=i+1;
        return new int[]{
            duplicate,missing
        };
    }
}

code.kotlin:
class Solution {
    fun findErrorNums(nums:IntArray):IntArray{
        var duplicate=0;
        var missing=0;
        for(item in nums){
            val value=kotlin.math.abs(item);
            val index=value-1;
            if(nums[index]<0)duplicate=value else nums[index]=-nums[index]
        };
        for(i in nums.indices)if(nums[i]>0)missing=i+1;
        return intArrayOf(duplicate,missing)
    }
}

